8	const TYPES_INCLUDED_IN_BASE_BONUS = 3;
9	const SPHINX_POINTS = 1;
10	const BASE_BONUS = 1;
11	const BONUS_PER_EXTRA_TYPE = 2;
12	
13	const bonusForVariety = (distinctTypeCount: number): number => {
14	  const typesBeyondBase = distinctTypeCount - TYPES_INCLUDED_IN_BASE_BONUS;
15	  return typesBeyondBase > 0
16	    ? BONUS_PER_EXTRA_TYPE * typesBeyondBase
17	    : BASE_BONUS;
