20	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
21	
22	// A Sphinx scores the distinct types it can see: every card except itself.
23	// Dropping the first Sphinx leaves any second Sphinx in view, so the Sphinx
24	// type counts exactly when the army holds more than one.
25	const typesSeenByASphinx = (army: Card[]): Set<string> => {
26	  const ownIndex = army.findIndex(isSphinx);
27	  const otherCards = army.filter((_card, index) => index !== ownIndex);
28	
29	  return new Set(otherCards.map((card) => card.monster));
30	};
