32	export const scoreArmy = (army: Card[]): number => {
33	  const sphinxCount = army.filter(isSphinx).length;
34	  const typeCount = typesSeenByASphinx(army).size;
35	
36	  return sphinxCount * (SPHINX_POINTS + bonusForVariety(typeCount));
37	};
