import { scoreArmy, type Card } from "./src/sphinx-score.js";

const permutations = <T,>(items: T[]): T[][] => {
  if (items.length <= 1) return [items];
  return items.flatMap((item, i) =>
    permutations([...items.slice(0, i), ...items.slice(i + 1)]).map((rest) => [item, ...rest]),
  );
};

const cases: { army: Card[]; expected: number }[] = [
  { army: [{monster:"chimera"},{monster:"orthrus"},{monster:"zombie"}], expected: 0 },
  { army: [{monster:"sphinx"},{monster:"cyclops"}], expected: 2 },
  { army: [{monster:"sphinx"},{monster:"chimera"},{monster:"orthrus"}], expected: 2 },
  { army: [{monster:"sphinx"},{monster:"chimera"},{monster:"orthrus"},{monster:"zombie"},{monster:"hydra"}], expected: 3 },
  { army: [{monster:"sphinx"},{monster:"chimera"},{monster:"orthrus"},{monster:"zombie"},{monster:"hydra"},{monster:"cyclops"}], expected: 5 },
  { army: [{monster:"sphinx"},{monster:"sphinx"},{monster:"chimera"},{monster:"orthrus"}], expected: 4 },
  { army: [{monster:"sphinx"},{monster:"sphinx"},{monster:"chimera"},{monster:"orthrus"},{monster:"zombie"}], expected: 6 },
  { army: [{monster:"sphinx"},{monster:"undead-warrior",rank:1},{monster:"undead-warrior",rank:3},{monster:"chimera"}], expected: 2 },
  { army: [{monster:"sphinx"},{monster:"chimera"},{monster:"chimera"},{monster:"chimera"},{monster:"orthrus"},{monster:"orthrus"}], expected: 2 },
];

let failures = 0;
for (const { army, expected } of cases) {
  for (const perm of permutations(army)) {
    const actual = scoreArmy(perm);
    if (actual !== expected) {
      failures++;
      console.log(`MISMATCH expected=${expected} actual=${actual} order=${perm.map(c=>c.monster+(c.rank??"")).join(",")}`);
    }
  }
}
console.log(failures === 0 ? "ORDER-INDEPENDENT: all permutations agree" : `FAILURES: ${failures}`);
EOF
