  const scores = new Set(permutations(army).map(scoreArmy));
  const label = `[${army.map(c=>c.monster).join(",")||"empty"}]`;
  if (scores.size > 1) { inconsistent++; console.log(`ORDER-DEPENDENT ${label} -> {${[...scores].join(",")}}`); }
