const TYPES_INCLUDED_IN_BASE_BONUS = 3, BASE_BONUS = 1, BONUS_PER_EXTRA_TYPE = 2;
const ternary = (n: number) => { const b = n - TYPES_INCLUDED_IN_BASE_BONUS; return b > 0 ? BONUS_PER_EXTRA_TYPE * b : BASE_BONUS; };
const maxForm = (n: number) => Math.max(BASE_BONUS, BONUS_PER_EXTRA_TYPE * (n - TYPES_INCLUDED_IN_BASE_BONUS));
let diff = 0;
for (let n = 0; n <= 30; n++) if (ternary(n) !== maxForm(n)) { diff++; console.log(`n=${n} ternary=${ternary(n)} max=${maxForm(n)}`); }
console.log(diff === 0 ? "EQUIVALENT over n=0..30" : `DIFFERS in ${diff} cases`);
